var t=`0472-sutlac`;var n=`world-0472`;var o=`TR`;var a=`western-asia`;var r=4;var l=68;var s={en:`Sütlaç`,ua:`Сютлач`};var d={en:`A traditional dish from Türkiye, centered on white rice, whole cow milk, cornstarch. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Туреччина. Основні складники: білий рис, цільне коров'яче молоко, кукурудзяний крохмаль. Домашній варіант із кількостями продуктів за етапами приготування.`};var m=[{en:`Cook the listed ingredients in simmering water for about 28 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 28 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:28,i:[[`white-rice`,130,`g`],[`water`,450,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`whole-cow-milk`,950,`ml`],[`white-granulated-sugar`,155,`g`],[`cornstarch`,25,`g`],[`vanilla-extract`,6,`ml`]]},{en:`Add the listed ingredients to the pot. Keep at a gentle simmer for about 20 minutes, until tender and cooked through.`,ua:`Додайте зазначені складники до каструлі. Варіть за слабкого кипіння приблизно 20 хвилин до м’якості та готовності.`,t:[`simmering`],m:20,i:[]},{en:`Bake in a preheated 180°C oven for about 12 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 12 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:12,i:[]}];var u={slug:t,id:n,country:`TR`,region:a,servings:4,minutes:68,title:s,text:d,steps:m};export{o as country,u as default,n as id,l as minutes,a as region,r as servings,t as slug,m as steps,d as text,s as title};